// ===== 看剧AI 订阅源共享库 v3（kanju.ai / kanju44.com 线路）=====
// 全站 /v1 接口需 HMAC-SHA256：报文 = 方法 + \n + 路径?查询 + \n + timestamp + \n + nonce
//
// 【v3 修复的真机坑】
// 1) 签名改用【纯 JS 实现】，不再依赖 Packages.javax.crypto.Mac
//    —— 真机 Rhino 里 `java` 会解析成内置 java 包对象（NativeJavaPackage），不是 legado 注入的 AnalyzeRule，
//       导致 java.ajax / java.get 报「不是函数，它是 object」。因此请求层也不能只依赖 java.ajax。
// 2) HTTP 三级兜底：java.ajax（函数才用）→ java.get/java.post（函数才用）→ Packages.java.net.URL（最可靠，实测可用）
// 3) 时间戳/nonce 不用 Packages.java.lang.System / UUID，改用 Date / Math.random，避免同类问题。
var KJ_SECRET = '557d0e4ae929f438da6bd84412374e6086b8af09b3fed54bf22601d5bf8c54a0';
var KJ_HOST = 'https://kanju44.com';
var KJ_PLAY = 'https://kanju44.com/p';
