function kjSyncHost(){
  try{
    var h = String(java.get('kj_host')||'');
    if(h && h.indexOf('http') === 0){ KJ_HOST = h; KJ_PLAY = h + '/p'; }
  }catch(e){}
  return KJ_HOST;
}
kjSyncHost();
var KJ_UA = 'Mozilla/5.0 (Linux; Android 16; 23113RKC6C) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/157.0.8103.38 Mobile Safari/537.36';
var KJ_KINDS = {'movie':'电影','series':'剧集','anime':'动漫','variety':'综艺','documentary':'纪录片','short_drama':'短剧','sports':'体育'};
var KJ_LASTERR = '';

function kjS(x){
