    var a=H[0], bb=H[1], c=H[2], dd=H[3], e=H[4], f=H[5], g=H[6], h=H[7];
    for(j=0;j<64;j++){
      var S1 = kjRotr(e,6) ^ kjRotr(e,11) ^ kjRotr(e,25);
      var ch = (e & f) ^ ((~e) & g);
