function kjHmacBytes(keyBytes, msgBytes){
  var bs = 64, k = keyBytes.slice(0), i;
  if(k.length > bs){ k = kjSha256(k); }
  while(k.length < bs){ k.push(0); }
  var ip = [], op = [];
  for(i=0;i<bs;i++){ ip.push(k[i] ^ 0x36); op.push(k[i] ^ 0x5c); }
  return kjSha256(op.concat(kjSha256(ip.concat(msgBytes))));
}
function kjRandHex(n){
  var s = '', i;
  for(i=0;i<n;i++){ s += ('0' + Math.floor(Math.random() * 16).toString(16)).slice(-1); }
  return s;
}
// ---------- 签名 / 请求头 ----------
function kjHmac(msg){
  return kjHexOf(kjHmacBytes(kjUtf8(KJ_SECRET), kjUtf8(msg)));
}
function kjHdrs(method, path){
  var ts = String(new Date().getTime());
  var nonce = kjRandHex(32);
  var m = kjS(method).toUpperCase();
  var sig = kjHmac(m + '\n' + kjS(path) + '\n' + ts + '\n' + nonce);
  return {
    'User-Agent': KJ_UA,
    'Accept': 'application/json, text/plain, */*',
    'Accept-Language': 'zh-CN,zh;q=0.9',
    'x-ai-movie-client-name': 'dianyingtiantang-frontend',
    'x-ai-movie-client-version': '1.0.0',
    'x-ai-movie-build-version': 'dianyingtiantang-v2026.11.06.2-search-header-f6f73501a448-web',
    'x-ai-movie-protocol-version': '2026-07-05.library-v2.playback-v1',
    'x-ai-movie-timestamp': ts,
    'x-ai-movie-nonce': nonce,
    'x-ai-movie-signature': sig
