}
// 返回 "url,{请求参数}"，供规则 URL / java.ajax 使用
function kjSigned(full, path, method){
  try{
    var m = kjS(method).toUpperCase();
    var o = {headers: kjHdrs(m, path)};
    if(m !== 'GET'){ o.method = m; }
    return kjS(full) + ',' + JSON.stringify(o);
  }catch(e){
    KJ_LASTERR = 'sign:' + String(e);
    return kjS(full);
  }
}
// ---------- HTTP：三级兜底 ----------
function kjIsFn(o, k){
  try{ return o !== null && o !== undefined && typeof o[k] === 'function'; }catch(e){ return false; }
}
// 原生 HttpURLConnection 通道（真机最可靠，实测 Packages.java.net.URL 可用）
function kjRaw(url, method, headers, body){
  var m = kjS(method || 'GET').toUpperCase();
  var conn = new Packages.java.net.URL(kjS(url)).openConnection();
  conn.setRequestMethod(m);
  conn.setConnectTimeout(15000);
  conn.setReadTimeout(25000);
  conn.setInstanceFollowRedirects(true);
  var h = headers || {};
  for(var key in h){
    try{ conn.setRequestProperty(String(key), kjS(h[key])); }catch(e0){}
  }
  if(m !== 'GET' && body !== null && body !== undefined && kjS(body)){
    conn.setDoOutput(true);
    var os = conn.getOutputStream();
    os.write(Packages.java.lang.String(kjS(body)).getBytes('UTF-8'));
    os.flush();
    os.close();
  }
  var is = conn.getInputStream();
  var br = new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(is, 'UTF-8'));
  var sb = new Packages.java.lang.StringBuilder();
  var ln = br.readLine();
  while(ln !== null){
    sb.append(ln);
    sb.append('\n');
    ln = br.readLine();
  }
  br.close();
  is.close();
  return String(sb.toString());
}
function kjBody(r){
  if(r === null || r === undefined){ return ''; }
  try{ var b = r.body(); if(b !== null && b !== undefined){ return String(b); } }catch(e){}
  return String(r);
}
function kjReq(path, method, body){
  var m = kjS(method || 'GET').toUpperCase();
  var h = kjHdrs(m, path);
  var url = kjS(KJ_HOST + kjS(path));
  var bs = (body === null || body === undefined) ? null : kjS(body);
  KJ_LASTERR = '';

  // ① java.ajax（仅在确实是函数时用；真机可能是 NativeJavaPackage）
  if(kjIsFn(typeof java !== 'undefined' ? java : null, 'ajax')){
    try{
      var o = {headers: h, method: m};
      if(m !== 'GET' && bs){ o.body = bs; }
      var r = java.ajax(url + ',' + JSON.stringify(o));
      var t = kjBody(r);
      if(t && t.length > 2){ return t; }
    }catch(e1){ KJ_LASTERR = 'ajax:' + String(e1); }
  }
  // ② java.get / java.post
  var jv = (typeof java !== 'undefined') ? java : null;
  if(m === 'GET' && kjIsFn(jv, 'get')){
    try{
      var t2 = kjBody(java.get(url, JSON.stringify(h)));
      if(t2 && t2.length > 2){ return t2; }
    }catch(e2){ KJ_LASTERR += ' | get:' + String(e2); }
  } else if(m !== 'GET' && kjIsFn(jv, 'post')){
    try{
      var hh = {};
      for(var k2 in h){ hh[k2] = h[k2]; }
      hh['Content-Type'] = 'application/json';
      var t3 = kjBody(java.post(url, bs, JSON.stringify(hh)));
      if(t3 && t3.length > 2){ return t3; }
    }catch(e3){ KJ_LASTERR += ' | post:' + String(e3); }
  }
