  try{
    var hdr = {};
    for(var k3 in h){ hdr[k3] = h[k3]; }
    if(m !== 'GET'){ hdr['Content-Type'] = 'application/json'; }
    var t4 = kjRaw(url, m, hdr, bs);
    if(t4 && t4.length > 2){ return t4; }
