}
function kjJson(s){
  if(s === null || s === undefined){ return {}; }
  if(typeof s === 'object'){ return s; }
  try{ var o = JSON.parse(String(s)); if(o && typeof o === 'object'){ return o; } }catch(e){}
  return {};
}
function kjObj(x){
  if(x === null || x === undefined){ return {}; }
  if(typeof x === 'string'){ return kjJson(x); }
  if(typeof x === 'object'){ return x; }
  return {};
}
function kjF(x, k){
  if(x === null || x === undefined){ return ''; }
  x = kjObj(x);
  var v = null;
  try{ if(typeof x.get === 'function'){ v = x.get(k); } }catch(e1){}
  if(v === null || v === undefined){ try{ v = x[k]; }catch(e2){} }
