// ---------- 剧集 / 线路 ----------
function kjEpInfo(b){
  var s = String(b||'');
  var cut = s.indexOf(',{');
  if(cut > 0){ s = s.slice(0, cut); }
  var r = {d:'', a:'', k:'', n:0, t:''};
  var m = /[?&]d=([^&#]*)/.exec(s);
  if(m){ r.d = kjDec(m[1]); }
  m = /[?&]a=([^&#]*)/.exec(s);
  if(m){ r.a = kjDec(m[1]); }
  m = /[?&]k=([^&#]*)/.exec(s);
  if(m){ r.k = kjDec(m[1]); }
  m = /[?&]n=(\d+)/.exec(s);
  if(m){ r.n = parseInt(m[1], 10) || 0; }
  m = /[?&]t=([^&#]*)/.exec(s);
  if(m){ r.t = kjDec(m[1]); }
  return r;
}
function kjResolve(ticket){
