// ===== 看剧AI 内容页：自建播放页（对齐荔枝短剧的做法）=====
// ruleContent = @js:KJ_PAGE(result, baseUrl) → 返回完整 HTML，由 Legado 内置浏览器渲染：
// 详情卡 + 线路条 + 选集网格 + 全屏 HLS 播放器（连点三下切 UI、上下滑切集、选集抽屉）。
// 页面内 JS 用 WebCrypto 复算 HMAC-SHA256 签名，直接同源 fetch 站点 /v1 接口取每集线路。
function KJ_ESC(s){
  s = kjS(s);
  return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}
function KJ_J(x){
  // 安全嵌入 <script>：把 < 转成 \u003c，防 </script> 截断
  return kjS(JSON.stringify(x)).replace(/</g, '\\u003c');
}
function KJ_ERR(msg){
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'
    + '<style>html,body{background:#0f1117;color:#e8eaf2;font-family:system-ui,-apple-system,sans-serif}'
    + '.e{padding:26px 20px;line-height:1.8}.e h3{color:#ff88a8;font-size:16px;margin-bottom:10px}.e p{font-size:13px;color:#a9aec4}</style>'
    + '</head><body><div class="e"><h3>播放页加载失败</h3><p>' + KJ_ESC(msg) + '</p></div></body></html>';
}
function KJ_PAGE(r, bu){
