    var det = kjJson(kjReq(kjDetailPath(id), 'GET'));
    if(!det || (!det.title && !det.episodes)){
      return KJ_ERR('详情接口未返回数据' + (KJ_LASTERR ? ('（' + KJ_LASTERR + '）') : '') + '，可稍后重试或更换线路域名。');
    }
    var rawEps = det.episodes || [];
