        +  '"https://cdnjs.cloudflare.com/ajax/libs/hls.js/1.5.13/hls.min.js"],i=0;'
        +  'function L(){if(i>=U.length){window.KJ_NO_HLS=1;if(window.KJ_READY){try{window.KJ_READY();}catch(e){}}return;}'
        +  'var s=document.createElement("script");s.src=U[i++];'
        +  's.onload=function(){if(window.KJ_READY){try{window.KJ_READY();}catch(e){}}};'
        +  's.onerror=function(){s.onload=null;s.onerror=null;L();};document.head.appendChild(s);}L();})();</scr' + 'ipt>';
    out += '</body></html>';
    return out;
  }catch(e){
    return KJ_ERR(String((e && e.message) ? e.message : e));
