}

// ===== 看剧AI 内容页：线路与选集合并为同一个交互 UI =====
// 设计：底部只有一个「选集/线路」抽屉。抽屉顶部是横向可滚动的线路标签，
// 切换线路后，下方网格立刻换成【该线路】的选集（每集的播放地址都随线路走）。
function KJ_UI_MAIN(){
  var D = (typeof KJ !== 'undefined') ? KJ : window.KJ;
  function $(i){ return document.getElementById(i); }
  var V=$('vd'), OV=$('ov'), ST=$('st'), TTL=$('ttl'), TIP=$('tip'), DL=$('dl'), DLG=$('dlg'), DT=$('dlt');
  var CURIDX=0, CURLINE=0, hls=null, uiHidden=false, LINEBAD={}, CUR_LINES=null;
  var SKIP_HEAD=0, SKIP_TAIL=0, AUTO_NEXT=true, ENDED_GUARD=0;
  // 按线路缓存每集地址：EPMAP[lineIndex][epIndex] = {u:'', tk:'', k:''}
  var EPMAP={}, EPOK={};

  function st(t){ if(!ST){return;} if(t){ ST.textContent=t; ST.style.display='block'; } else { ST.style.display='none'; } }
  function tip(t){ if(!TIP){return;} TIP.textContent=t; TIP.classList.add('s'); setTimeout(function(){ TIP.classList.remove('s'); },1300); }

  // ---------- 纯 JS SHA-256 / HMAC ----------
  function rotr(x,n){ return (x>>>n)|(x<<(32-n)); }
  function sha256(b){
    var K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
    var H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    var l=b.length, bits=l*8, d=b.slice(0);
    d.push(0x80); while(d.length%64!==56){ d.push(0); }
    var hi=Math.floor(bits/4294967296), lo=bits>>>0;
    d.push((hi>>>24)&255,(hi>>>16)&255,(hi>>>8)&255,hi&255,(lo>>>24)&255,(lo>>>16)&255,(lo>>>8)&255,lo&255);
    var w=new Array(64), i, j;
    for(i=0;i<d.length;i+=64){
      for(j=0;j<16;j++){ w[j]=(d[i+j*4]<<24)|(d[i+j*4+1]<<16)|(d[i+j*4+2]<<8)|d[i+j*4+3]; }
      for(j=16;j<64;j++){
        var s0=rotr(w[j-15],7)^rotr(w[j-15],18)^(w[j-15]>>>3);
        var s1=rotr(w[j-2],17)^rotr(w[j-2],19)^(w[j-2]>>>10);
        w[j]=(w[j-16]+s0+w[j-7]+s1)|0;
      }
      var a=H[0],bb=H[1],c=H[2],dd=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
      for(j=0;j<64;j++){
        var S1=rotr(e,6)^rotr(e,11)^rotr(e,25), ch=(e&f)^((~e)&g);
        var t1=(h+S1+ch+K[j]+w[j])|0;
        var S0=rotr(a,2)^rotr(a,13)^rotr(a,22), maj=(a&bb)^(a&c)^(bb&c);
        var t2=(S0+maj)|0;
        h=g;g=f;f=e;e=(dd+t1)|0;dd=c;c=bb;bb=a;a=(t1+t2)|0;
      }
      H[0]=(H[0]+a)|0;H[1]=(H[1]+bb)|0;H[2]=(H[2]+c)|0;H[3]=(H[3]+dd)|0;
      H[4]=(H[4]+e)|0;H[5]=(H[5]+f)|0;H[6]=(H[6]+g)|0;H[7]=(H[7]+h)|0;
    }
    var out=[]; for(i=0;i<8;i++){ out.push((H[i]>>>24)&255,(H[i]>>>16)&255,(H[i]>>>8)&255,H[i]&255); }
    return out;
  }
  function u8(s){
    var o=[],i,c; s=String(s);
    for(i=0;i<s.length;i++){
      c=s.charCodeAt(i);
      if(c<0x80){ o.push(c); }
      else if(c<0x800){ o.push(0xc0|(c>>6),0x80|(c&63)); }
      else { o.push(0xe0|(c>>12),0x80|((c>>6)&63),0x80|(c&63)); }
    }
    return o;
  }
  function hmacHex(k,m){
    var bs=64, kk=u8(k), i;
    if(kk.length>bs){ kk=sha256(kk); }
    while(kk.length<bs){ kk.push(0); }
    var ip=[],op=[];
    for(i=0;i<bs;i++){ ip.push(kk[i]^0x36); op.push(kk[i]^0x5c); }
    var dg=sha256(op.concat(sha256(ip.concat(u8(m)))));
    var s=''; for(i=0;i<dg.length;i++){ s+=('0'+dg[i].toString(16)).slice(-2); }
    return s;
  }
  function randHex(n){ var s='',i; for(i=0;i<n;i++){ s+=Math.floor(Math.random()*16).toString(16); } return s; }

  function hdrs(method,path){
    var ts=String(Date.now()), no=randHex(32);
    var msg=[String(method).toUpperCase(),path,ts,no].join('\n');
    return {'x-ai-movie-client-name':'dianyingtiantang-frontend',
      'x-ai-movie-client-version':'1.0.0',
      'x-ai-movie-build-version':'dianyingtiantang-v2026.11.06.2-search-header-f6f73501a448-web',
      'x-ai-movie-protocol-version':'2026-07-05.library-v2.playback-v1',
      'x-ai-movie-timestamp':ts,'x-ai-movie-nonce':no,
      'x-ai-movie-signature':hmacHex(D.secret,msg),'Accept':'application/json'};
  }
  function req(path,method,body,depth){
    depth = depth||0;
    var m = String(method||'GET').toUpperCase();
    var h = hdrs(m,path), full = D.host+path;
    var bs = body ? JSON.stringify(body) : null;
    if(window.java && typeof window.java.ajax === 'function'){
      try{
        var opt={method:m,headers:h};
        if(m!=='GET' && bs){ opt.headers['Content-Type']='application/json'; opt.body=bs; }
        var t0=String(window.java.ajax(full+','+JSON.stringify(opt))||'');
        var j0=null; try{ j0=JSON.parse(t0); }catch(e0){}
        if(j0){ return Promise.resolve(j0); }
      }catch(e1){}
    }
    var o={method:m,headers:h,cache:'no-store'};
    if(m!=='GET' && bs){ o.headers['Content-Type']='application/json'; o.body=bs; }
    return fetch(full,o).then(function(r){ return r.text(); }).then(function(t){
      var j=null; try{ j=JSON.parse(t); }catch(e){}
      if(j){ return j; }
      if(depth<1){ return req(path,m,body,depth+1); }
      return null;
    });
  }

  // ---------- 线路 / 剧集 ----------
  function pickLines(d){
    var lo=(d&&d.line_options)?d.line_options:[], dir=[], tix=[], i;
    for(i=0;i<lo.length;i++){
      var L=lo[i]||{}, u=String(L.url||'');
      var lb=String(L.display_label||L.label||L.provider_name||('线路'+(i+1)));
      var w=parseFloat(L.preference_weight)||0;
      if(u.indexOf('http')===0){ dir.push({l:lb,u:u,tk:'',w:w,k:'d'}); }
      else if(u.indexOf('resolve://')===0){ tix.push({l:lb,u:'',tk:u.slice(10),w:w,k:'t'}); }
    }
    dir.sort(function(a,b){ return b.w-a.w; });
    tix.sort(function(a,b){ return b.w-a.w; });
    return dir.concat(tix);
  }
  function getLines(tok){
    if(!tok){ return Promise.resolve([]); }
    if(D.__lc && D.__lc[tok]){ return Promise.resolve(D.__lc[tok]); }
    return req('/v1/playback/resolve/'+encodeURIComponent(tok),'GET').then(function(d){
      var L=pickLines(d||{});
      D.__lc = D.__lc||{}; D.__lc[tok]=L;
      return L;
    });
  }
  function resolveTicket(tk){
    return req('/v1/playback/resolve-line','POST',{ticket:String(tk||'')}).then(function(d){
      return String((d&&d.line&&d.line.url)||'');
    });
  }
  // 取「某线路 × 某集」的可播地址（带缓存）
  function markEpOk(lineIdx, epIdx, ok){
    if(!EPOK[lineIdx]){ EPOK[lineIdx]={}; }
    EPOK[lineIdx][epIdx]=!!ok;
  }
  function epOk(lineIdx, epIdx){
    if(EPOK[lineIdx] && typeof EPOK[lineIdx][epIdx]!=='undefined'){ return EPOK[lineIdx][epIdx]; }
    return undefined;
  }
  function getEpUrl(lineIdx, epIdx){
    var key = lineIdx+'|'+epIdx;
    if(EPMAP[key]){ return Promise.resolve(EPMAP[key]); }
    var e = D.eps[epIdx];
    if(!e || !e.t){ markEpOk(lineIdx,epIdx,false); return Promise.resolve(null); }
    return getLines(e.t).then(function(L){
      var it = L[lineIdx];
      if(!it){ markEpOk(lineIdx,epIdx,false); return null; }
      if(it.k==='t'){
        return resolveTicket(it.tk).then(function(u){
          if(!u){ markEpOk(lineIdx,epIdx,false); return null; }
          var v={u:u,tk:'',k:'t'};
          EPMAP[key]=v; markEpOk(lineIdx,epIdx,true); return v;
        });
      }
      var v={u:it.u,tk:'',k:'d'};
      EPMAP[key]=v; markEpOk(lineIdx,epIdx,true); return v;
    });
  }
  // 当前线路下的剧集索引表（过滤掉已知不可用的集）
  function lineEps(){
    var out=[];
    for(var i=0;i<D.eps.length;i++){
      if(epOk(CURLINE,i)===false){ continue; }
      out.push(i);
    }
    return out.length ? out : (function(){ var a=[]; for(var j=0;j<D.eps.length;j++){ a.push(j); } return a; })();
  }

  // ---------- 全屏 / 方向 ----------
  function isFullscreen(){
    try{ if(document.fullscreenElement || document.webkitFullscreenElement){ return true; } }catch(e){}
    var w=window.innerWidth||0, h=window.innerHeight||0;
    return w>0 && h>0 && (w/h)>=1.15;
  }
  function lockDir(dir){
    try{
      if(screen && screen.orientation && typeof screen.orientation.lock==='function'){
        var p=screen.orientation.lock(dir);
        if(p&&p.catch){ p.catch(function(){}); }
        return true;
      }
    }catch(e){}
    try{ if(typeof screen!=='undefined'&&screen.lockOrientation){ screen.lockOrientation(dir); return true; } }catch(e){}
    try{ if(typeof screen!=='undefined'&&screen.mozLockOrientation){ screen.mozLockOrientation(dir); return true; } }catch(e){}
    return false;
  }
  function unlockDir(){
    try{ if(screen&&screen.orientation&&typeof screen.orientation.unlock==='function'){ screen.orientation.unlock(); return; } }catch(e){}
    try{ if(typeof screen!=='undefined'&&screen.unlockOrientation){ screen.unlockOrientation(); } }catch(e){}
  }
  function autoLandscape(){ if(isFullscreen()){ lockDir('landscape'); } }
  function fitBox(){
    try{
      var w=V.videoWidth||0, h=V.videoHeight||0;
      if(!w||!h){ return; }
      var sw=window.innerWidth||0, sh=window.innerHeight||0;
      if(!sw||!sh){ return; }
      var vr=w/h, sr=sw/sh;
      if(vr>sr){ V.style.width='100%'; V.style.height=Math.round(sw/vr)+'px'; }
      else { V.style.height='100%'; V.style.width=Math.round(sh*vr)+'px'; }
      V.style.objectFit='contain';
    }catch(e){}
  }

  function killHls(){ if(hls){ try{ hls.destroy(); }catch(e){} hls=null; } }

  function startPlay(url,label){
    if(!url){ st('未取到播放地址，可点右上「原站」观看'); return; }
    st('加载中…');
    if(TTL&&label){ TTL.textContent=label; }
    killHls();
    ENDED_GUARD = 0;
    if(!(window.Hls && window.Hls.isSupported())){
      if(window.KJ_NO_HLS){ V.src=url; st(''); try{ V.play(); }catch(e){} applySkip(); return; }
      window.KJ_PEND={u:url,l:label}; st('播放器加载中…'); return;
    }
    try{
      hls=new window.Hls({maxBufferLength:30});
      hls.loadSource(url);
      hls.attachMedia(V);
      hls.on(window.Hls.Events.MANIFEST_PARSED,function(){
        st(''); try{ V.play(); }catch(e){}
        applySkip(); autoLandscape();
      });
      hls.on(window.Hls.Events.ERROR,function(e,data){
        if(!data||!data.fatal){ return; }
        st('本条线路播放失败，正在换线路…');
        lineFail();
      });
    }catch(e2){ st('播放器初始化失败'); }
  }

  // ---------- 片头片尾跳过 ----------
  function applySkip(){
    if(SKIP_HEAD<=0){ return; }
    var tries=0;
    function once(){
      try{
        if(V && V.currentTime < SKIP_HEAD){
          V.currentTime = SKIP_HEAD;
          V._headDone = true;
          tip('已跳过片头 '+SKIP_HEAD+'s');
        }
      }catch(e){}
      tries++;
      if(tries<4){ setTimeout(once, 250); }
    }
    once();
  }
  function onTimeUpdate(){
    if(!V || !V.duration){ return; }
    if(SKIP_HEAD>0 && V.currentTime>0.2 && V.currentTime < SKIP_HEAD-0.3 && !V._headDone){
      try{ V.currentTime = SKIP_HEAD; }catch(e){}
      return;
    }
    if(SKIP_HEAD>0){ V._headDone = V.currentTime >= SKIP_HEAD-0.3; }
    if(SKIP_TAIL>0 && V.duration>0){
      var tailStart = V.duration - SKIP_TAIL;
      if(V.currentTime >= tailStart && tailStart>0){ onEnded('tail'); }
    }
  }

  // ---------- 播完自动下一集 ----------
  function onEnded(reason){
    if(!AUTO_NEXT){ st('播放结束'); return; }
    var now = Date.now();
    if(now - ENDED_GUARD < 1500){ return; }
    ENDED_GUARD = now;
    var list = lineEps();
    var pos = list.indexOf(CURIDX);
    if(pos < 0){ pos = 0; }
    if(pos + 1 < list.length){
      tip('播放结束，自动下一集');
      openAt(list[pos+1]);
    } else {
      st('已是当前线路的最后一集');
    }
  }

  function ep(){ return D.eps[CURIDX]||{}; }
  function label(){ var e=ep(); return D.title+' 第'+e.n+'集'; }

  // 播放当前集 × 当前线路
  function playCur(){
    var tok=String(ep().t||'');
    if(!tok){ st('该集缺少播放凭证'); return; }
    getLines(tok).then(function(L){
      if(!L.length){ st('该集暂无可用线路'); return; }
      CUR_LINES=L; rebuildLineTabs(L);
      if(CURLINE>=L.length){ CURLINE=0; }
      markLine(CURLINE);
      st('加载中…');
      getEpUrl(CURLINE,CURIDX).then(function(v){
        if(!v){ lineFail(); return; }
        startPlay(v.u,label());
      });
    }).catch(function(){ st('线路获取失败，可点右上「原站」'); });
  }
  function lineFail(){
    getLines(String(ep().t||'')).then(function(L){
      CUR_LINES=L; rebuildLineTabs(L);
      LINEBAD[CURLINE]=1; markLine(CURLINE);
      var i, pick=-1;
      for(i=1;i<=L.length;i++){ var k=(CURLINE+i)%L.length; if(!LINEBAD[k]){ pick=k; break; } }
      if(pick<0){ st('全部线路都失败，可点右上「原站」或稍后重试'); LINEBAD={}; return; }
      CURLINE=pick;
      EPMAP={};
      markLine(CURLINE);
      playCur();
    }).catch(function(){ st('换线路失败'); });
  }

  // ---------- 合并 UI：线路标签 + 该线路的选集 ----------
  function rebuildLineTabs(L){
    var el=$('linetabs');
    if(!el){ return; }
    el.innerHTML='';
    for(var i=0;i<L.length;i++){
      (function(ix){
        var b=document.createElement('button');
        b.className='lt';
        b.setAttribute('data-i',String(ix));
        b.textContent=String(L[ix].l||('线路'+(ix+1)))+(L[ix].k==='t'?'·票':'');
        b.onclick=function(ev){
          if(ev){ ev.stopPropagation(); }
          if(ix===CURLINE){ return; }
          CURLINE=ix;
          if(!(CUR_LINES && CUR_LINES.length)){
            // 首屏还没取过线路表：先拉一次再标记
            getLines(String(ep().t||'')).then(function(L2){
              CUR_LINES=L2; markLine(ix); buildEpsForLine();
              if(OV.classList.contains('s')){ playCur(); }
            });
          } else {
            markLine(ix);
            buildEpsForLine();
            if(OV.classList.contains('s')){ playCur(); }
          }
          tip('已切到线路 '+(ix+1)+'，上下集只在本线路内切换');
        };
        el.appendChild(b);
      })(i);
    }
  }
  function markLine(i){
    var a=document.querySelectorAll('#linetabs button.lt'), k, b;
    for(k=0;k<a.length;k++){
      b=a[k];
      if(parseInt(b.getAttribute('data-i'),10)===i){ b.classList.add('on'); } else { b.classList.remove('on'); }
    }
    // 线路数据源：优先当前集的线路表，其次首屏注入的线路名表
    var L=(CUR_LINES&&CUR_LINES.length)?CUR_LINES:D.lines;
    var it=L[i]||{};
    var nm=String(it.l||('线路'+(i+1)));
    var led=$('led');
    if(led){ led.textContent='线路 '+(i+1)+'/'+L.length+' · '+nm+(it.k==='t'?'（票）':''); }
    var cur=$('curline');
    if(cur){ cur.textContent=nm; }
  }
  // 按当前线路重建选集网格
  function buildEpsForLine(){
    var g=$('grid');
    if(!g){ return; }
    g.innerHTML='';
    for(var i=0;i<D.eps.length;i++){
      (function(ix){
        var b=document.createElement('button');
        b.className='eb';
        b.setAttribute('data-i',String(ix));
        b.setAttribute('data-n',String(D.eps[ix].n));
        b.textContent=String(D.eps[ix].n);
        if(epOk(CURLINE,ix)===false){ b.classList.add('na'); }  // 当前线路无此集
        if(ix===CURIDX){ b.classList.add('on'); }
        b.onclick=function(ev){ if(ev){ ev.stopPropagation(); } openAt(ix); };
        g.appendChild(b);
      })(i);
    }
    // 抽屉内的选集网格同步
    if(DLG && DL && DL.getAttribute('data-kind')==='eps'){ buildDrawerEps(); }
  }
  function buildDrawerEps(){
    if(!DLG){ return; }
    DLG.className='';
    DLG.innerHTML='';
    var head=document.createElement('div');
    head.className='dlsub';
    head.textContent='当前线路：'+(function(){ var L=CUR_LINES||D.lines, it=L[CURLINE]||{}; return String(it.l||('线路'+(CURLINE+1))); })();
    DLG.appendChild(head);
    var wrap=document.createElement('div');
    wrap.className='dlgrid';
    for(var i=0;i<D.eps.length;i++){
      (function(ix){
        var b=document.createElement('button');
        b.className='db';
        b.setAttribute('data-i',String(ix));
        b.textContent=String(D.eps[ix].n);
        if(epOk(CURLINE,ix)===false){ b.classList.add('na'); }
        if(ix===CURIDX){ b.classList.add('on'); }
        b.onclick=function(ev){ if(ev){ ev.stopPropagation(); } closeDrawer(); openAt(ix); };
        wrap.appendChild(b);
      })(i);
    }
    DLG.appendChild(wrap);
    var act=DLG.querySelector('button.db.on');
    if(act){ try{ act.scrollIntoView({block:'center'}); }catch(e){} }
  }

  function markEp(){
    var a=document.querySelectorAll('button.eb'), b, i, k;
    for(i=0;i<a.length;i++){
      b=a[i];
      if(parseInt(b.getAttribute('data-i'),10)===CURIDX){ b.classList.add('on'); } else { b.classList.remove('on'); }
    }
    var dlg=DLG?DLG.querySelectorAll('button.db'):[];
    for(k=0;k<dlg.length;k++){
      b=dlg[k];
      if(parseInt(b.getAttribute('data-i'),10)===CURIDX){ b.classList.add('on'); } else { b.classList.remove('on'); }
    }
    var epn=$('epn'); if(epn){ epn.textContent='选集·'+ep().n; }
  }

  function openAt(i){
    if(!D.eps[i]){ return; }
    // 若该集在当前线路已知不可用，自动顺延到本线路最近的可用集
    if(epOk(CURLINE,i)===false){
      var list=lineEps(), k, pick=-1, best=1e9;
      for(k=0;k<list.length;k++){
        var d2=Math.abs(list[k]-i);
        if(d2<best){ best=d2; pick=list[k]; }
      }
      if(pick>=0){ tip('该集在当前线路不可用，已切到第'+D.eps[pick].n+'集'); i=pick; }
    }
    CURIDX=i;
    killHls();
    OV.classList.add('s');
    setUI(true);
    closeDrawer();
    markEp();
    if(TTL){ TTL.textContent=label(); }
    st('加载中…');
    playCur();
  }
  function nb(d){
    // 只在【当前线路】的剧集范围内上下集
    var list = lineEps();
    var pos = list.indexOf(CURIDX);
    if(pos < 0){ pos = 0; }
    var np = pos + d;
    if(np < 0){ tip('已经是当前线路的第一集'); return; }
    if(np >= list.length){ tip('已经是当前线路的最后一集'); return; }
    openAt(list[np]);
  }
  function setUI(show){
    uiHidden=!show;
    if(OV){ if(show){ OV.classList.remove('hide'); } else { OV.classList.add('hide'); } }
  }
  function toggleUI(){ setUI(uiHidden); tip(uiHidden?'连点三下唤出菜单':'连点三下隐藏菜单'); }
  function closeDrawer(){ if(DL){ DL.classList.remove('s'); } }

  // 抽屉：只有一个，内含线路标签 + 选集
  function drawerOpen(){
    if(!DL){ return; }
    DT.textContent='选集 / 线路';
    DL.setAttribute('data-kind','eps');
    DL.classList.add('s');
    buildDrawerEps();
  }

  // ---------- 设置面板 ----------
  function skipPanel(){
    if(!DL){ return; }
    DT.textContent='播放设置';
    DL.setAttribute('data-kind','set');
    DL.classList.add('s');
    DLG.className='dbl';
    DLG.innerHTML='';
    var rows=[['片头（秒）', SKIP_HEAD, 'head'],['片尾（秒）', SKIP_TAIL, 'tail']];
    for(var i=0;i<rows.length;i++){
      (function(name,val,key){
        var box=document.createElement('div');
        box.className='setrow';
        var lab=document.createElement('span');
        lab.className='setlab'; lab.textContent=name;
        box.appendChild(lab);
        var inp=document.createElement('input');
        inp.type='number'; inp.className='setinp'; inp.value=String(val||0);
        inp.onclick=function(ev){ if(ev){ ev.stopPropagation(); } };
        box.appendChild(inp);
        var btn=document.createElement('button');
        btn.className='setbtn'; btn.textContent='确定';
        btn.onclick=function(ev){
          if(ev){ ev.stopPropagation(); }
          var v=parseInt(inp.value,10);
          if(!v||v<0||v>3600){ v=0; }
          if(key==='head'){ SKIP_HEAD=v; } else { SKIP_TAIL=v; }
          saveCfg(); tip(name+' = '+v+' 秒'); applySkip();
        };
        box.appendChild(btn);
        DLG.appendChild(box);
      })(rows[i][0], rows[i][1], rows[i][2]);
    }
    var auto=document.createElement('div');
    auto.className='setrow';
    var alab=document.createElement('span');
    alab.className='setlab'; alab.textContent='播完自动下一集';
    auto.appendChild(alab);
    var ab=document.createElement('button');
    ab.className='setbtn'+(AUTO_NEXT?' on':'');
    ab.textContent=AUTO_NEXT?'已开启':'已关闭';
    ab.onclick=function(ev){
      if(ev){ ev.stopPropagation(); }
      AUTO_NEXT=!AUTO_NEXT;
      ab.textContent=AUTO_NEXT?'已开启':'已关闭';
      if(AUTO_NEXT){ ab.classList.add('on'); } else { ab.classList.remove('on'); }
      saveCfg();
    };
    auto.appendChild(ab);
    DLG.appendChild(auto);
    var hint=document.createElement('div');
    hint.className='sethint';
    hint.textContent='片头：起播自动跳到该秒数；片尾：剩余该秒数时视为播完（自动下一集）。0 = 不跳过。设置保存在本机。';
    DLG.appendChild(hint);
  }
  function cfgKey(){ return 'kj_skip_'+String(D.id||''); }
  function loadCfg(){
    try{
      var raw=localStorage.getItem(cfgKey());
      if(!raw){ return; }
      var o=JSON.parse(raw);
      if(o){
        SKIP_HEAD=parseInt(o.h,10)||0;
        SKIP_TAIL=parseInt(o.t,10)||0;
        AUTO_NEXT=(o.a===0)?false:true;
      }
    }catch(e){}
  }
  function saveCfg(){
    try{ localStorage.setItem(cfgKey(),JSON.stringify({h:SKIP_HEAD,t:SKIP_TAIL,a:AUTO_NEXT?1:0})); }catch(e){}
  }

  function bindStatic(){
    var p1=$('play1'); if(p1){ p1.onclick=function(){ openAt(CURIDX); }; }
    var eb=document.querySelectorAll('button.eb'), k;
    for(k=0;k<eb.length;k++){
      (function(b){ b.onclick=function(){ openAt(parseInt(b.getAttribute('data-i'),10)); }; })(eb[k]);
    }
    var cl=$('cl');
    if(cl){
      cl.onclick=function(e){
        if(e){ e.stopPropagation(); }
        OV.classList.remove('s'); closeDrawer(); unlockDir();
        try{ V.style.width=''; V.style.height=''; }catch(e2){}
        killHls();
        try{ V.pause(); V.removeAttribute('src'); V.load(); }catch(e3){}
      };
    }
    var pv=$('pv'); if(pv){ pv.onclick=function(e){ if(e){ e.stopPropagation(); } nb(-1); }; }
    var nx=$('nx'); if(nx){ nx.onclick=function(e){ if(e){ e.stopPropagation(); } nb(1); }; }
    var epn=$('epn'); if(epn){ epn.onclick=function(e){ if(e){ e.stopPropagation(); } drawerOpen(); }; }
    var ln=$('ln'); if(ln){ ln.onclick=function(e){ if(e){ e.stopPropagation(); } drawerOpen(); }; }
    var sk=$('sk'); if(sk){ sk.onclick=function(e){ if(e){ e.stopPropagation(); } skipPanel(); }; }
    var dlc=$('dlc'); if(dlc){ dlc.onclick=function(e){ if(e){ e.stopPropagation(); } closeDrawer(); }; }
    if(DLG){
      var dty=0;
      DLG.addEventListener('touchstart',function(e){ if(e.touches.length===1){ dty=e.touches[0].clientY; } },false);
      DLG.addEventListener('touchend',function(e){
        if(e.changedTouches&&e.changedTouches.length){
          var dy=e.changedTouches[0].clientY-dty;
          if(dy>70){ closeDrawer(); }
        }
      },false);
    }
    V.addEventListener('loadedmetadata',function(){ fitBox(); autoLandscape(); applySkip(); },false);
    V.addEventListener('resize',function(){ fitBox(); },false);
    V.addEventListener('timeupdate',onTimeUpdate,false);
    V.addEventListener('ended',function(){ onEnded('ended'); },false);
    V.addEventListener('playing',function(){
      if(SKIP_HEAD>0 && V.currentTime < SKIP_HEAD-0.5){
        try{ V.currentTime=SKIP_HEAD; V._headDone=true; tip('已跳过片头 '+SKIP_HEAD+'s'); }catch(e){}
      }
    },false);
    V.addEventListener('loadeddata',function(){ applySkip(); },false);
    V.addEventListener('canplay',function(){ applySkip(); },false);
    window.addEventListener('resize',function(){ fitBox(); autoLandscape(); },false);
    document.addEventListener('fullscreenchange',function(){ autoLandscape(); fitBox(); },false);
    document.addEventListener('webkitfullscreenchange',function(){ autoLandscape(); fitBox(); },false);

    var tcount=0, ttimer=null, sy=0, sx=0, moved=false;
    function onTap(){
      tcount++;
      if(ttimer){ clearTimeout(ttimer); }
      ttimer=setTimeout(function(){ tcount=0; },700);
      if(tcount>=3){ tcount=0; toggleUI(); }
    }
    V.addEventListener('touchstart',function(e){
      moved=false;
      if(e.touches.length!==1){ return; }
      sy=e.touches[0].clientY; sx=e.touches[0].clientX;
    },false);
    V.addEventListener('touchmove',function(e){
      if(e.touches.length!==1){ return; }
      var dy=e.touches[0].clientY-sy;
      if(dy>16||dy<-16){ moved=true; }
    },false);
    V.addEventListener('touchend',function(e){
      var dy=0,dx=0;
      if(e.changedTouches&&e.changedTouches.length){
        dy=e.changedTouches[0].clientY-sy;
        dx=e.changedTouches[0].clientX-sx;
      }
      if(Math.abs(dy)>56&&Math.abs(dy)>Math.abs(dx)*1.4){
        if(dy<0){ nb(1); } else { nb(-1); }
        moved=true; return;
      }
      if(!moved){ onTap(); }
    },false);
    if(OV){
      OV.addEventListener('click',function(e){
        var t=e.target; if(!t){ return; }
        var tg=String(t.tagName||'').toUpperCase();
        if(tg==='BUTTON'||tg==='A'||tg==='VIDEO'||tg==='INPUT'){ return; }
        onTap();
      },false);
    }
  }

  window.KJ_READY=function(){
    if(!window.KJ_PEND){ return; }
    var p=window.KJ_PEND; window.KJ_PEND=null;
    startPlay(p.u,p.l);
  };

  loadCfg();
  bindStatic();
  // 用 JS 接管线路标签（静态 HTML 里的按钮没有事件，这里统一重建并绑定）
  rebuildLineTabs((CUR_LINES && CUR_LINES.length) ? CUR_LINES : D.lines);
  buildEpsForLine();
  markEp();
  markLine(0);
  st('点「立即播放」或任一集开始播放');
  if(!D.lines.length){ st('本片暂无线路数据，可点右上「原站」'); }
}

