function kjlIsFn(o,k){ try{ return o!==null && o!==undefined && typeof o[k]==='function'; }catch(e){ return false; } }
// 取文本：java.ajax(函数时) → java.get(函数时) → Packages.java.net.URL
function kjlGetText(url){
  var h = kjlHdrs('GET', String(url).replace(/^https?:\/\/[^\/]+/,''));
  var jv = (typeof java!=='undefined') ? java : null;
  if(kjlIsFn(jv,'ajax')){
    try{
      var t = String(java.ajax(url+','+JSON.stringify({headers:h}))||'');
      if(t && t.length>2){ return t; }
    }catch(e1){}
  }
  if(kjlIsFn(jv,'get')){
    try{
      var t2 = String(java.get(url, JSON.stringify(h))||'');
      if(t2 && t2.length>2){ return t2; }
    }catch(e2){}
  }
  try{
    var conn=new Packages.java.net.URL(url).openConnection();
    conn.setRequestMethod('GET');
    conn.setConnectTimeout(8000);
    conn.setReadTimeout(8000);
    conn.setInstanceFollowRedirects(true);
    for(var k in h){ try{ conn.setRequestProperty(String(k),String(h[k])); }catch(e3){} }
    var is=conn.getInputStream();
    var br=new Packages.java.io.BufferedReader(new Packages.java.io.InputStreamReader(is,'UTF-8'));
    var sb=new Packages.java.lang.StringBuilder();
    var ln=br.readLine();
    while(ln!==null){ sb.append(ln); ln=br.readLine(); }
    br.close(); is.close();
    return String(sb.toString());
  }catch(e4){ return ''; }
}
function kjlCurHost(){
  var h='';
  try{ h=String(java.get('kj_host')||''); }catch(e){}
  if(!h || h.indexOf('http')!==0){ h=KJ_DEFAULT_HOST; }
  return h;
}
function kjlPing(host){
  var t0=new Date().getTime();
  try{
    var txt=kjlGetText(host+'/v1/browse/catalog?page=1&limit=1');
    if(!txt || txt.indexOf('"cards"')<0){ return -1; }
    return new Date().getTime()-t0;
  }catch(e){ return -1; }
}

