    });
  }

  rows.push({name:'🔍 测速全部域名', type:'button', action:'ping',
    style:{layout_flexGrow:1, layout_flexBasisPercent:1}});

  var res = st.res;
  if(res && res.length){
    rows.push({name:'—— 测速结果（毫秒，越小越快）——', type:'label',
      style:{layout_flexGrow:1, layout_flexBasisPercent:1}});
    for(var j=0;j<res.length;j++){
      var r = res[j] || {};
      var ms = (r.ms >= 0) ? (r.ms + ' ms') : '—';
      rows.push({name: String(r.h||'').replace('https://','') + ' : ' + ms + (r.best?' ⭐':''),
        type:'label', style:{layout_flexGrow:1, layout_flexBasisPercent:1}});
    }
  }
  if(st.note){
    rows.push({name:String(st.note), type:'label',
      style:{layout_flexGrow:1, layout_flexBasisPercent:1}});
  }
  return JSON.stringify({rows:rows});
}

function loginAction(action, state, form){
  var st = {};
  try{ st = (typeof state==='string') ? JSON.parse(state) : (state||{}); }catch(e){ st={}; }
  var a = String(action||'');

  if(a.indexOf('use:') === 0){
    var host = a.slice(4);
    try{ java.put('kj_host', host); }catch(e){}
    return JSON.stringify({state:{cur:host, res:st.res||null,
      note:'已切换到 ' + host + '，返回并刷新列表即可生效。'}});
  }

  if(a === 'ping'){
    var out=[], best=-1, bestHost='';
    for(var i=0;i<KJ_DOMAINS.length;i++){
      var h=KJ_DOMAINS[i];
      var ms=kjlPing(h);
      out.push({h:h, ms:ms, best:false});
      if(ms>=0 && (best<0 || ms<best)){ best=ms; bestHost=h; }
    }
    for(var j=0;j<out.length;j++){ if(out[j].h===bestHost){ out[j].best=true; } }
    out.sort(function(x,y){
      if(x.ms<0 && y.ms<0){ return 0; }
      if(x.ms<0){ return 1; }
      if(y.ms<0){ return -1; }
      return x.ms-y.ms;
    });
    var note = bestHost ? ('最快：' + bestHost + '（' + best + ' ms），点它即可切换。') : '全部域名都不通，请检查网络。';
    return JSON.stringify({state:{cur:kjlCurHost(), res:out, note:note}});
  }

  return JSON.stringify({state:st});
}


// ============ V1 动态面板（LT + legado-E 双版本通吃）261117 ============
// 根因：原 loginUi={"version":2} 是 V2 面板，E 版无 V2 delegate → GSON.fromJsonArray 失败 → 面板空白。
// 关键差异（vs 小说书源）：本订阅源全程用 java.get/put('kj_host')（jsLib 规则层共享 java 键空间），
//   而 evalUiJs（V1 动态生成函数）环境【无 java、有 source】。
//   故：action 里选线时 java.put('kj_host') 让规则层生效 + source.put('kjv_host') 存显示镜像；
//       kjV1Rows 从 source.get('kjv_host') 读显示值。测速结果存 source.get/put。
function kjvGV(k, def) {
  var v = '';
  try { v = String(source.get(k) || ''); } catch (e) {}
  if (!v || v === 'null' || v === 'undefined') v = def || '';
  return v;
}
function kjvPV(k, v) { try { source.put(k, String(v)); } catch (e) {} }
function kjvCurHost() {
  var v = kjvGV('kjv_host', '');
  return (v && v.indexOf('http') === 0) ? v : KJ_DEFAULT_HOST;
}
function kjvRows() {
  var W1 = { layout_flexGrow: 1, layout_flexBasisPercent: 1 };
  var W2 = { layout_flexGrow: 1, layout_flexBasisPercent: 0.48 };
  var R = [];
  var cur = kjvCurHost();
  var note = kjvGV('kjv_note', '');
  var ping = kjvGV('kjv_ping', '');
  var pingMap = {};
  try { pingMap = JSON.parse(kjvGV('kjv_ping_map', '{}')); } catch (e) {}
  // 说明行/状态行一律用 button（E 版 label 不渲染），点击=查看/刷新
  R.push({ name: '看剧AI · 视频订阅源（8 条线路域名）', type: 'button', action: 'kjvHelp(java)', style: W1 });
  R.push({ name: '① 点域名切换线路 ② 点测速看延迟 ③ 播放失败先换低延迟域名', type: 'button', action: 'kjvHelp(java)', style: W1 });
  R.push({ name: '④ 播放页连点3下隐藏UI，再连点3下唤出UI', type: 'button', action: 'kjvHelp(java)', style: W1 });
  R.push({ name: '当前域名：' + cur.replace('https://', '') + (ping ? ('  ' + ping) : ''), type: 'button', action: 'kjvPing(java)', style: W1 });
  var best = kjvGV('kjv_best', '');
  for (var i = 0; i < KJ_DOMAINS.length; i++) {
    var d = KJ_DOMAINS[i];
    var mk = (d === cur ? ' ✅' : '');
    if (pingMap[d] !== undefined) mk = (pingMap[d] >= 0 ? ' ' + pingMap[d] + 'ms' : ' ✖') + (d === best ? '⭐' : '');
    R.push({ name: d.replace('https://', '') + mk, type: 'button', action: "kjvUse(java,'" + d + "')", style: W2 });
  }
  R.push({ name: '🔍 测速全部域名', type: 'button', action: 'kjvPing(java)', style: W1 });
  if (note) R.push({ name: String(note), type: 'button', action: 'kjvHelp(java)', style: W1 });
  return JSON.stringify(R);
}
function kjvRefresh(jv, msg) {
  if (msg) kjvPV('kjv_note', msg);
  try { jv.longToast(String(msg || '')); } catch (e) { try { jv.toast(String(msg || '')); } catch (e2) {} }
  try { jv.reLoginView(true); } catch (e3) { try { jv.reUiView(true); } catch (e4) {} }
  return 'ok';
}
function kjvHelp(jv) {
  return kjvRefresh(jv, '点域名切换线路（列表/搜索/播放都走新域名）；测速后点最快的那个。');
}
function kjvUse(jv, host) {
  host = String(host || '');
  try { java.put('kj_host', host); } catch (e) {}   // 规则层生效（java 键空间）
  kjvPV('kjv_host', host);                          // 显示镜像（source 键空间）
  return kjvRefresh(jv, '已切换到 ' + host.replace('https://', '') + '，返回并刷新列表生效。');
}
function kjvPing(jv) {
  var map = {}, out = [], bestMs = -1, bestHost = '', i, h, ms;
  for (i = 0; i < KJ_DOMAINS.length; i++) {
    h = KJ_DOMAINS[i];
    ms = kjlPing(h);
    map[h] = ms;
    if (ms >= 0 && (bestMs < 0 || ms < bestMs)) { bestMs = ms; bestHost = h; }
  }
  kjvPV('kjv_ping_map', JSON.stringify(map));
  if (bestHost) kjvPV('kjv_best', bestHost);
  kjvPV('kjv_ping', bestHost ? ('最快 ' + bestHost.replace('https://', '') + ' ' + bestMs + 'ms') : '全部不通');
  var detail = [];
  for (h in map) { detail.push(h.replace('https://', '') + (map[h] >= 0 ? (map[h] + 'ms') : '✖')); }
  return kjvRefresh(jv, '测速：' + detail.join(' / '));
}
